824	def contains_unpaired_surrogate(text):
825	    """True if text holds an unpaired UTF-16 surrogate code point (U+D800..U+DFFF).
826	
827	    A syntactically legal JSON body can still contain one via an unpaired
828	    ``\\uD800``/``\\uDC00`` escape. Such a code point cannot be encoded as
829	    UTF-8, so it must be rejected as a content error of the specific field
830	    before saving: otherwise encoding the response later aborts the request
831	    without returning the validation result the caller expects. Correctly
832	    paired escapes decode to a single astral character (e.g. an emoji) and
833	    never match this check.
834	    """
835	    return any(0xD800 <= ord(ch) <= 0xDFFF for ch in text)
