838	def surrogate_content_error(field_label, text):
839	    """Build a 400 message naming the field that holds an unpaired surrogate.
840	
841	    The offending code point is shown as U+XXXX instead of embedding the
842	    broken character, so the error message itself is always UTF-8 encodable
843	    and the error response stays parseable JSON.
844	    """
845	    for ch in text:
846	        if 0xD800 <= ord(ch) <= 0xDFFF:
847	            return (
848	                f"{field_label}包含无法编码保存的字符"
849	                f"（未配对的 Unicode 代理码点 U+{ord(ch):04X}），"
850	                f"请删除或修改该字符后重试"
851	            )
852	    raise AssertionError("text contains no unpaired surrogate")
