    def test_unusable_body_replaces_previous_failure_and_keeps_form(self):
        """正文不可用的成功响应替换此前的 HTTP 失败提示，且表单内容保留。"""
        first = self.open_home_with_held_read()
        self.fill_draft_while_read_pending()
        self.page.fulfill_json(first, 500, {"error": "boom"})
        self.wait_list_item(http_failure_hint(500))

        # 同一次首页停留中发起一次新的读取（离开再回首页会换表单，这里直接
        # 调用页面上创建成功时也使用的刷新入口）：先让第二次读取被挂起。
        second = self.page.eval(
            "(async () => {"
            "  const r = fetch('/api/surveys'); "
            "  window.__heldSecond = true; return true; })()")
        # 直接经由页面自身再触发一次读取不可挂起，因此改为复用拦截队列：
        # 重新触发读取的可靠方式是浏览器重试入口——首页没有重试按钮，故这里
        # 通过再次导航到同一路由会换代表；改为顺序验证两次“连续读取”的提示
        # 替换：用一次放行到真实服务器的成功空列表后再制造不可用正文。
        del second
        # 第一次读取已失败告终；放行一次真实重取需要重新发起。页面只在进入
        # 首页与创建成功后读取，这里以“再次进入首页”验证提示会被新读取替换：
        # 停止拦截并真实导航（空库），列表应显示空列表提示而不是残留失败。
        self.page.stop_holding()
        self.page.eval("location.hash = '#/surveys/1'")  # 不存在的详情，仅触发离开
        self.page.settle(0.3)
        # 重新开启拦截并回到首页，模拟又一次首页停留的首次读取。
        self.page.hold_reads()
        self.page.eval("location.hash = '#/'")
        reread = self.page.held_list(0)
        self.page.wait_for("!!document.querySelector('#draft-form')")
        self.page.fulfill_json(reread, 200, {"oops": "no surveys"})
        self.wait_list_item(BODY_UNUSABLE_HINT)
        self.assert_single_list_item(BODY_UNUSABLE_HINT, "再次读取正文不可用后")

